#!/bin/sh
# Regression tests for library_sched.
#
#   1. tests/expected/NAME.ALG.out  must equal  library_sched inputs/NAME.txt ALG
#      (expected files were worked out by hand, not generated by the program)
#   2. every file in tests/invalid/ must be rejected with a non-zero exit code
#   3. every input x every algorithm must be deterministic (two runs identical)
#      and satisfy basic invariants (one row per reader, WT >= 0, RT <= WT).
#
# Run from the project root:  make test   (or ./tests/run_tests.sh)

cd "$(dirname "$0")/.." || exit 1
BIN=./library_sched
pass=0
fail=0

ok()  { pass=$((pass + 1)); }
bad() { fail=$((fail + 1)); echo "FAIL: $1"; }

[ -x "$BIN" ] || { echo "build first: make"; exit 1; }

# 1. Expected outputs -------------------------------------------------
for exp in tests/expected/*.out; do
    base=$(basename "$exp" .out)          # e.g. sample.PRIORITY
    name=${base%.*}
    alg=${base##*.}
    if "$BIN" "tests/inputs/$name.txt" "$alg" | diff -u "$exp" - > /dev/null; then
        ok
    else
        bad "$name $alg differs from expected:"
        "$BIN" "tests/inputs/$name.txt" "$alg" | diff -u "$exp" -
    fi
done

# 2. Invalid inputs ---------------------------------------------------
for f in tests/invalid/*.txt; do
    if "$BIN" "$f" FCFS > /dev/null 2>&1; then
        bad "$f was accepted"
    else
        ok
    fi
done
if "$BIN" tests/inputs/sample.txt NOT_AN_ALGORITHM > /dev/null 2>&1; then
    bad "unknown algorithm was accepted"
else
    ok
fi

# 3. Determinism and invariants ---------------------------------------
for f in tests/inputs/*.txt; do
    n=$(head -n 1 "$f" | tr -d '[:space:]')
    for alg in FCFS PRIORITY PRIORITY_PREEMPTIVE RR SJF; do
        a=$("$BIN" "$f" "$alg")
        b=$("$BIN" "$f" "$alg")
        [ "$a" = "$b" ] && ok || bad "$f $alg is not deterministic"

        rows=$(printf '%s\n' "$a" | sed -n '2,/^SUMMARY$/p' | grep -vc '^SUMMARY$')
        [ "$rows" -eq "$n" ] && ok || bad "$f $alg: $rows rows, expected $n"

        # cols: 1 id,2 arr,3 pri,4 svc,5 start,6 compl,7 wt,8 tat,9 rt
        msg=$(printf '%s\n' "$a" | sed -n '2,/^SUMMARY$/p' | grep -v '^SUMMARY$' |
              awk -F, '$7 < 0 || $9 < 0 || $9 > $7 || $8 != $6 - $2 || $7 != $8 - $4 \
                       || $5 < $2 { print $1 }')
        [ -z "$msg" ] && ok || bad "$f $alg: invariant broken for $msg"
    done
done

echo "passed: $pass  failed: $fail"
[ "$fail" -eq 0 ]
